            let status = res.status();
            let matched_path = res.text().await;
            assert_eq!(status, StatusCode::OK, "Router");

            let inner = Router::new()
                .route(
                    $route_path,
                    get(|matched: MatchedPath| async move { matched.as_str().to_owned() }),
                )
                .boxed_clone();
